      "i": 8,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "अब बताइए variant में क्या prefer करेंगे milk more, super या कोई और?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "बस करो चाहिए।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "ठीक है आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "Hello क्या आप अभी line पे हैं?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "जी जी बताइए।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "जैसा कि मैंने बताया मैं आपको seller details WhatsApp कर दूंगी।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
